import{_ as t,a,o as n,a6 as r}from"./chunks/framework.CJDy2q7X.js";const f=JSON.parse('{"title":"Refunds","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/sales/refunds/index.md","filePath":"api/rest-api/admin/sales/refunds/index.md","lastUpdated":1786429091000}'),s={name:"api/rest-api/admin/sales/refunds/index.md"};function d(o,e,i,u,h,p){return n(),a("div",null,e[0]||(e[0]=[r('<h1 id="refunds" tabindex="-1">Refunds <a class="header-anchor" href="#refunds" aria-label="Permalink to &quot;Refunds&quot;">​</a></h1><p>The Refunds menu is the store-wide, <strong>read-only</strong> list of every refund that has been issued across all orders. It mirrors the admin <strong>Sales → Refunds</strong> screen — browse refunds, open one for detail, and export the list. It does not create refunds (that happens against an order — see below).</p><h2 id="when-a-row-appears-here" tabindex="-1">When a row appears here <a class="header-anchor" href="#when-a-row-appears-here" aria-label="Permalink to &quot;When a row appears here&quot;">​</a></h2><p>A refund row exists only after a refund has been <strong>issued</strong> for an order. A refund records money returned to the customer for some or all of the order&#39;s items, plus an optional adjustment-refund (an extra amount returned beyond the line items) and an optional adjustment-fee (an amount withheld from the refund). Placing, invoicing, or shipping an order does not by itself create a refund; until one is issued, the order has no row in this menu.</p><p>Issuing a refund is an <strong>order action</strong>, not part of this menu — it runs against a specific order under <a href="/api/rest-api/admin/sales/orders/create-refund.html">Orders → Create Refund</a> (with a <a href="/api/rest-api/admin/sales/orders/refund-preview.html">Refund Preview</a> to compute totals first).</p><h2 id="refunded-amount" tabindex="-1">Refunded Amount <a class="header-anchor" href="#refunded-amount" aria-label="Permalink to &quot;Refunded Amount&quot;">​</a></h2><p>The list&#39;s <strong>Refunded Amount</strong> is the refund&#39;s grand total in the store&#39;s base currency (subtotal + tax + shipping + adjustment-refund − adjustment-fee) — not just the line-items subtotal. In the API payload this is <code>formattedBaseGrandTotal</code> (raw: <code>baseGrandTotal</code>).</p><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/sales/refunds/list.html">List refunds</a></td><td><code>GET /api/admin/refunds</code></td></tr><tr><td><a href="/api/rest-api/admin/sales/orders/get-refund.html">Get a single refund</a></td><td><code>GET /api/admin/refunds/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/sales/refunds/export.html">Export refunds (CSV)</a></td><td><code>GET /api/admin/refunds/export</code></td></tr></tbody></table><p>All Refunds endpoints require the <code>sales.refunds.view</code> permission and an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',10)]))}const m=t(s,[["render",d]]);export{f as __pageData,m as default};
